proveedores = [
    {"nombre": "proveedor-nube-a", "acceso_datos": "alto", "certificacion_iso27001": True, "criticidad_negocio": 3, "incidentes_ultimos_2_anios": 0},
    {"nombre": "proveedor-nomina-b", "acceso_datos": "alto", "certificacion_iso27001": False, "criticidad_negocio": 2, "incidentes_ultimos_2_anios": 1},
    {"nombre": "proveedor-limpieza-c", "acceso_datos": "bajo", "certificacion_iso27001": False, "criticidad_negocio": 1, "incidentes_ultimos_2_anios": 0},
]

PESO_ACCESO = {"alto": 30, "medio": 15, "bajo": 5}

def puntuacion_riesgo(p):
    puntos = PESO_ACCESO[p["acceso_datos"]]
    puntos += 0 if p["certificacion_iso27001"] else 20
    puntos += p["criticidad_negocio"] * 10
    puntos += p["incidentes_ultimos_2_anios"] * 15
    return puntos

def nivel(puntos):
    if puntos >= 60:
        return "alto - auditoria anual obligatoria"
    if puntos >= 30:
        return "medio - revision semestral"
    return "bajo - revision anual"

for p in sorted(proveedores, key=puntuacion_riesgo, reverse=True):
    puntos = puntuacion_riesgo(p)
    print(f"{p['nombre']}: {puntos} puntos -> riesgo {nivel(puntos)}")
